static GLuint shader(GLenum t,const char*s){GLuint x=glCreateShader(t);glShaderSource(x,1,&s,0);glCompileShader(x);GLint ok;glGetShaderiv(x,GL_COMPILE_STATUS,&ok);assert(ok);return x;}
static void scene(GLuint p){glClear(GL_COLOR_BUFFER_BIT|GL_DEPTH_BUFFER_BIT|GL_STENCIL_BUFFER_BIT);GLint u=glGetUniformLocation(p,"offset");glUniform2f(u,0,-0.5f);glDrawArrays(GL_TRIANGLES,0,3);glUniform2f(u,0,0.5f);glDrawElements(GL_TRIANGLES,3,GL_UNSIGNED_SHORT,0);glUniform2f(u,4,0);glDrawArrays(GL_TRIANGLES,0,3);}
int main(void){assert(SDL_Init(SDL_INIT_VIDEO)==0);SDL_GL_SetAttribute(SDL_GL_CONTEXT_PROFILE_MASK,SDL_GL_CONTEXT_PROFILE_ES);SDL_GL_SetAttribute(SDL_GL_CONTEXT_MAJOR_VERSION,3);SDL_GL_SetAttribute(SDL_GL_DEPTH_SIZE,24);SDL_GL_SetAttribute(SDL_GL_STENCIL_SIZE,8);SDL_Window*w=SDL_CreateWindow("probe",0,0,64,64,SDL_WINDOW_OPENGL|SDL_WINDOW_HIDDEN);assert(w);assert(SDL_GL_CreateContext(w));GLuint p=glCreateProgram();glAttachShader(p,shader(GL_VERTEX_SHADER,"#version 300 es\nuniform vec2 offset;void main(){vec2 v[3]=vec2[3](vec2(-.8,-.8),vec2(.8,-.8),vec2(0,.8));gl_Position=vec4(v[gl_VertexID]+vec2(offset.x,0),offset.y,1);}"));glAttachShader(p,shader(GL_FRAGMENT_SHADER,"#version 300 es\nprecision mediump float;out vec4 color;void main(){color=vec4(1,0,0,1);}"));glLinkProgram(p);glUseProgram(p);GLuint ib;GLushort ids[3]={0,1,2};glGenBuffers(1,&ib);glBindBuffer(GL_ELEMENT_ARRAY_BUFFER,ib);glBufferData(GL_ELEMENT_ARRAY_BUFFER,sizeof ids,ids,GL_STATIC_DRAW);glEnable(GL_DEPTH_TEST);glDepthFunc(GL_LESS);glViewport(0,0,64,64);unsigned char a[64*64*4],b[sizeof a];scene(p);glReadPixels(0,0,64,64,GL_RGBA,GL_UNSIGNED_BYTE,a);int(*begin)(unsigned)=dlsym(RTLD_DEFAULT,"ds_gl_cost_begin");void(*present)(void)=dlsym(RTLD_DEFAULT,"ds_gl_cost_present");assert(begin&&present&&begin(1));scene(p);glReadPixels(0,0,64,64,GL_RGBA,GL_UNSIGNED_BYTE,b);present();assert(!memcmp(a,b,sizeof a));assert(glGetError()==GL_NO_ERROR);GLboolean d,c[4];glGetBooleanv(GL_DEPTH_WRITEMASK,&d);glGetBooleanv(GL_COLOR_WRITEMASK,c);assert(d&&c[0]&&c[1]&&c[2]&&c[3]&&glIsEnabled(GL_DEPTH_TEST));puts("PASS identical pixels, restored depth/color state, no GL errors");SDL_Quit();}
